class C1(Exception):
    def __init__(self, code, msg):
        self.code = code
        self.msg = msg

def f1(flag):
    if flag:
        raise C1(452, 'fail')
    return 0

try:
    f1(True)
except C1 as e:
    print(e.code, e.msg)

class C2(Exception):
    def __init__(self, code, msg):
        self.code = code
        self.msg = msg

class C1:
    def __enter__(self):
        return self
    def __exit__(self, exc_type, exc_val, tb):
        if exc_val is not None:
            print('handled:', exc_val.code, exc_val.msg)
            return False
        return False

try:
    with C1():
        raise C2(365, 'err')
except C2 as e:
    print('outer caught:', e.code, e.msg)

